// ---- ท่อน late2 (เดิมอยู่ app.js บรรทัด 7265) · ห่อ: duelAct ----
(function(){const SL=globalThis.__wSlots['late2'];let duelAct=SL.base.duelAct;
duelAct=function(a){if(!DU)return;duClear();
 const e=DU.intent,myP=(DU.ar?myPow():total())*(has('plasma')?1.6:1),ratio=DU.ar?Math.max(.05,Math.min(20,myP/DU.ep)):Math.max(.35,Math.min(3,myP/DU.ep)),rr=()=>.8+Math.random()*.4,fast=DU._t0&&Date.now()-DU._t0<2500;
 let md=22*Math.pow(ratio,.7)*rr()*(1+.15*Math.min(3,DU.combo||0)),ed=22/Math.pow(ratio,.7)*rr()*(DU.charge?1.8:1)*(S.ch==='hell'?1.15:1);
 if(a==='flee'){S.hp-=R(5,15);DU.txt='คุณถอยหนีออกจากวงต่อสู้';return duelEnd(false,true)}
 let t='',good=null;const tn=`《${DU.tech||''}》`;
 if(duelX(a,e==='heavy'||e==='feint'?'atk':e,md,ed))t=DU._t;
 else if(a==='none'){const early=DU._ea;DU._ea=0;if(e==='atk'){DU.me-=ed;t=`${early?'⚡ ศัตรูไม่รอ! ':'⏳ ช้าไป! '}${tn}กระแทกเข้าเต็มๆ`}else if(e==='heavy'){DU.me-=ed*1.6;t=`${early?'⚡ ศัตรูชิงลงมือก่อน! ':'⏳ ช้าไป! '}${tn}ท่าหนักซัดคุณกระเด็น`}else if(e==='feint'){DU.me-=ed*.5;t='⏳ คุณลังเล ศัตรูแทงเบาๆ ทิ้งท้ายแล้วถอยออกไป'}else if(e==='chg'){t='⏳ ศัตรูรวมพลังเสร็จโดยไม่มีใครขัด…'}else t='⏳ ต่างฝ่ายต่างจ้องกันจนหมดจังหวะ';good=false;sfx('hit')}
 else if(a==='atk'){if(e==='atk'){DU.en-=md;DU.me-=ed*.8;t='ทั้งคู่พุ่งเข้าปะทะ! กระบี่กระทบกันเสียงดังสนั่น';good=null}else if(e==='heavy'){DU.en-=md*.8;DU.me-=ed*1.5;t=`คุณบุกสวนทาง${tn}ท่าหนัก แลกกันแต่คุณเจ็บกว่า`;good=false}else if(e==='feint'){DU.en-=md*1.1;t='ศัตรูแค่หลอก คุณบุกเข้าไปจังๆ!';good=true}else if(e==='def'){DU.en-=md*.35;DU.me-=ed*.4;t='คุณบุก แต่ศัตรูตั้งรับไว้แน่น แล้วสวนกลับมา';good=false}else{DU.en-=md*1.5;t='คุณบุกเข้าไปขณะศัตรูรวมพลัง! ขัดจังหวะได้อย่างสวยงาม';good=true}sfx('hit')}
 else if(a==='def'){if(e==='atk'){DU.en-=md*.45;DU.me-=ed*.25;t='คุณรับการบุกไว้ได้ แล้วผลักกลับไปเล็กน้อย';good=true}else if(e==='heavy'){DU.me-=ed*.8;t=`${tn}ท่าหนักทุบการ์ดคุณแตก!`;good=false}else if(e==='feint'){t='คุณตั้งรับท่าหลอก เสียจังหวะไปเปล่าๆ';good=false}else if(e==='def'){DU.me=Math.min(100,DU.me+5);t='ทั้งคู่ตั้งการ์ดจ้องกัน ต่างฝ่ายต่างหายใจหอบ'}else{DU.me=Math.min(100,DU.me+3);t='คุณตั้งรับ แต่ศัตรูฉวยโอกาสรวบรวมพลังได้สำเร็จ!';good=false}sfx('block')}
 else if(a==='dodge'){if(e==='heavy'){DU.en-=md*.5;t=`💨 คุณพลิกตัวหลบ${tn}ได้ฉิวเฉียด แล้วฉวยช่องโหว่ตอบโต้!`;good=true}else if(e==='atk'){DU.en-=md*.15;t='💨 คุณหลบการบุกพ้น แต่ไม่มีจังหวะตอบโต้';good=true}else if(e==='feint'){DU.me-=ed*.3;t='💨 คุณหลบท่าหลอก… ศัตรูตามมาเฉี่ยวได้';good=false}else if(e==='chg'){t='💨 คุณหลบอยู่ทำไม ศัตรูรวมพลังเสร็จแล้ว!';good=false}else t='💨 คุณกระโดดหลบอากาศว่างเปล่า';sfx('block')}
 else if(a==='ctr'){if(e==='atk'){DU.en-=md*1.3;DU.me-=ed*.15;t='↩️ สวนกลับจังหวะเดียวกับที่ศัตรูพุ่งเข้ามา!';good=true}else if(e==='feint'){DU.en-=md*1.6;t='↩️ จับได้ว่าเป็นท่าหลอก สวนกลับเข้ากลางอก!';good=true}else if(e==='heavy'){DU.me-=ed*1.7;DU.en-=md*.3;t=`↩️ คุณพยายามสวน แต่${tn}หนักเกินจะรับ!`;good=false}else if(e==='def'){t='↩️ คุณรอสวนกลับ แต่ศัตรูไม่บุกเข้ามาเลย';good=false}else{t='↩️ คุณรอสวน ศัตรูกลับรวมพลังเสร็จ…';good=false}sfx('hit')}
 else if(a==='sec'){DU.secret=false;DU.en-=md*(e==='def'?1.9:2.2);if(e==='atk'||e==='heavy')DU.me-=ed*(e==='heavy'?1.1:.7);t=`คุณปล่อยวิชาลับ 《${DU.art}》 ออกไปเต็มกำลัง!`;sfx('rare');good=true}
 if(good===true){DU.combo=(DU.combo||0)+1;DU.reads=(DU.reads||0)+1;DU.best=Math.max(DU.best||0,DU.combo);if(fast&&a!=='sec'){DU.en-=md*.2;t+=' <b style="color:#f0c860">⚡ เร็ว!</b>'}if(DU.combo>=2)t+=` <span class="tag2">🔥 คอมโบ ×${DU.combo}</span>`}else if(good===false)DU.combo=0;
 DU.charge=(e==='chg'&&a!=='atk'&&a!=='sec');
 if(DU.poison){DU.en-=DU.poison;t+=` <span class="tag2">☠️ พิษ −${DU.poison}</span>`}
 if(DU.me<=0){const g=S.items.find(i=>i.id==='gun'&&i.left>0);if(g){g.left--;S.flags.gun=1;DU.en=0;DU.me=5;t+='<br>จวนตัว! คุณชักปืนออกมา <b>ปัง!</b>'}}
 DU.txt=t;DU.r++;
 if(DU.me<=0||DU.en<=0||DU.r>6){if((DU.best||0)>=4&&S)S.flags.duCombo=1;return duelEnd(DU.en<=0||(DU.me>0&&DU.r>6&&DU.me>DU.en))}
 DU.intent=duelIntent();drawDuel()};
SL.impl.duelAct=duelAct;duelAct=function(){return globalThis.duelAct.apply(this,arguments)};})();

