{const _f=fight;fight=function(n,e){let r=_f.apply(this,arguments);try{if(!r&&S&&S.alive&&!S.beastMode&&S.ch!=='hell'&&!window._duW){
 const fr=(S.mem||[]).filter(m=>m.v>=2);if(fr.length&&Math.random()<.12){const m=ch(fr);m.v--;log(`🤝 ${m.n}โผล่มาช่วยไว้ได้ทัน "ข้ายังไม่ลืมที่ท่าน${m.why}"`,'good');return true}
 if(mortal()&&!S.oneArm&&S.scar!=='arm'&&S.age>=16&&Math.random()<.03){S.oneArm=1;S.power=Math.max(1,S.power-pw(.08));seed('onearm',R(2,4));keyAdd(`เสียแขนข้างหนึ่งให้${String(n).replace(/<[^>]+>/g,'')}`);log(`🩸 ดาบของ${n}ตัดแขนซ้ายคุณขาด วิชาเดิมใช้ไม่ได้อีกแล้ว`,'bad')}}}catch(x){}return r}}
// ---------- 4) ปณิธานปลายทาง (ฉากจบหลายแบบ) ----------
const GOALS={
 lord:['👑 เจ้ายุทธภพ','ชื่อเสียงสูงสุด และไม่มีใครเอาชนะได้',()=>S.fame>=2000&&rep().sect>=20],
 hermit:['🏔️ ฤาษีหลบโลก','ปัญญาสูง กรรมดี ตัดขาดชื่อเสียง',()=>(S.int||0)>=NI()*1.3&&S.karma>=30],
 general:['🛡️ ขุนพลแผ่นดิน','ราชสำนักไว้ใจ ปกป้องบ้านเมือง',()=>rep().court>=40],
 demon:['😈 มารครองโลก','ฝ่ายมารยกย่อง ทั้งโลกหวาดกลัว',()=>rep().dem>=40&&S.karma<=-30],
 tycoon:['💰 มหาเศรษฐี','ร่ำรวยที่สุดในแผ่นดิน',()=>S.money>=100000],
 saint:['🧑‍🌾 นักบุญของชาวบ้าน','ชาวบ้านทั่วแผ่นดินบูชา',()=>rep().pp>=50],
 devoted:['❤️ ชีวิตเพื่อคนที่รัก','อยู่เคียงข้างคู่ชีวิตจนวันสุดท้าย',()=>!!S.spouse]};
function goalPick(){const o=Object.entries(GOALS).filter(([k])=>k!=='devoted'||S.spouse).map(([k,g])=>({t:g[0],s:g[1],noFate:1,f(){S.lg=k;S.lgp=0;log(`🏁 ปณิธานปลายทาง: <b>${g[0]}</b> เหตุการณ์ในชีวิตจะเริ่มเอนไปทางนี้`,'myth')}}));
 Ev('🏁 ครึ่งชีวิตแล้ว จะจบชีวิตแบบไหน',`ทางที่เลือกจะทำให้เหตุการณ์เปลี่ยนไป และตัดสินฉากจบของคุณ<br><span class="tag2">ฉากจบที่เคยเห็น ${(LS.get('murim_ends',[])||[]).length}/${Object.keys(GOALS).length+1}</span>`,o)}
const GEV={
 lord:()=>Ev('👑 ศึกชิงตำแหน่งเจ้ายุทธภพ','ยอดฝีมือจากทุกสำนักมารวมตัวที่ยอดเขา',[{t:'⚔️ ขึ้นเวที',s:'แรงกว่า 25%',f(){if(fight('ยอดฝีมือแห่งยุค',ep(1.25))){S.lgp++;S.fame+=300;rp({sect:15});log('👑 คุณยืนเป็นคนสุดท้ายบนเวที','epic')}else injure&&injure('ศึกชิงเจ้ายุทธภพ')}},{t:'🤝 ผูกมิตรกับเจ้าสำนักก่อน',s:'เงิน -20% · ปณิธานคืบช้า',f(){lose(.2);rp({sect:20});if(Math.random()<.5)S.lgp++}}]),
 hermit:()=>Ev('🏔️ เสียงเรียกจากโลก','ลูกศิษย์ขึ้นเขามาขอให้คุณกลับไปช่วยสำนักที่กำลังล่ม',[{t:'🏔️ ไม่ลงเขา',s:'ปณิธานคืบ · '+rpTxt({sect:-15}),f(){S.lgp++;S.int+=20;rp({sect:-15});log('🏔️ คุณนั่งสมาธิต่อ เสียงลูกศิษย์ค่อยๆ เงียบไป','')}},{t:'⬇️ ลงไปช่วย',s:'ปณิธานถอย · '+rpTxt({sect:20}),f(){S.lgp=Math.max(0,S.lgp-1);rp({sect:20});S.fame+=50}}]),
 general:()=>Ev('🛡️ ข้าศึกบุกชายแดน','ราชสำนักขอให้คุณนำทัพ แต่ต้องทิ้งครอบครัวไปหลายปี',[{t:'🛡️ นำทัพ',s:'สู้แรงกว่า 20% · ความสุขลด',f(){joy(-10);if(fight('แม่ทัพข้าศึก',ep(1.2))){S.lgp++;rp({court:20});log('🛡️ ชายแดนสงบ ฮ่องเต้พระราชทานยศ','epic')}else rp({court:-10})}},{t:'🏠 ปฏิเสธ',skip:1,s:rpTxt({court:-15}),f(){rp({court:-15})}}]),
 demon:()=>Ev('😈 เครื่องสังเวยของฝ่ายมาร','ผู้นำฝ่ายมารจะยอมรับคุณ ถ้าคุณทำลายวัดที่ชาวบ้านบูชา',[{t:'🔥 ทำลายวัด',s:rpTxt({dem:25,pp:-25})+' · กรรมชั่ว',f(){S.lgp++;S.karma-=30;rp({dem:25,pp:-25});log('🔥 เปลวไฟสีดำกลืนวัดทั้งหลัง','bad')}},{t:'✋ ไม่ทำ',s:rpTxt({dem:-15}),f(){rp({dem:-15})}}]),
 tycoon:()=>Ev('💰 โอกาสทองทางการค้า','เส้นทางสินค้าข้ามแคว้นเปิดใหม่ ลงทุนหนักได้กำไรมาก แต่ถ้าพลาดล้มละลาย',[{t:'💰 ทุ่มครึ่งหนึ่งของทั้งหมด',s:'60%: เงิน x2 · 40%: เสียครึ่ง',f(){const h=Math.floor(S.money/2);if(Math.random()<.6){S.money+=h*2;S.lgp++;log('💰 กองคาราวานกลับมาพร้อมทองเต็มเกวียน','epic')}else{S.money-=h;log('💰 คาราวานถูกปล้นกลางทะเลทราย','bad')}}},{t:'🪙 ลงทีละน้อย',s:'ปลอดภัย · ปณิธานคืบช้า',f(){S.money+=Math.round(S.money*.1);if(Math.random()<.35)S.lgp++}}]),
 saint:()=>Ev('🧑‍🌾 ภัยแล้งทั้งแคว้น','ชาวบ้านอดอยากเป็นหมื่น ช่วยได้แต่ต้องสละสิ่งที่สะสมมา',[{t:'🍚 เปิดยุ้งฉางของตัวเอง',s:'เงิน -40% · '+rpTxt({pp:25}),f(){lose(.4);S.lgp++;rp({pp:25});log('🍚 ชาวบ้านจุดธูปตั้งชื่อคุณไว้ทุกบ้าน','good')}},{t:'📢 บีบให้คหบดีช่วย',s:rpTxt({pp:15,court:-10}),f(){rp({pp:15,court:-10});if(Math.random()<.5)S.lgp++}}]),
 devoted:()=>Ev('❤️ คู่ชีวิตล้มป่วยหนัก','หมอบอกว่ามียาเพียงขนานเดียวที่ช่วยได้ อยู่บนยอดเขาที่ปีศาจเฝ้า',[{t:'⛰️ ไปเอายาเอง',s:'สู้แรงกว่า 20%',f(){if(fight('ปีศาจเฝ้ายา',ep(1.2))){S.lgp++;joy(15);log('❤️ คุณกลับมาทันพร้อมยา มือเธอบีบมือคุณแน่น','myth')}else{injure&&injure('ปีศาจเฝ้ายา');log('❤️ คุณไปไม่ถึง… แต่คู่ชีวิตยังสู้ต่อ','bad')}}},{t:'💰 จ้างคนไปเอา',s:'เงิน -30%',f(){lose(.3);if(Math.random()<.5)S.lgp++}}])};
function ending(){if(!S||!S.lg||!GOALS[S.lg])return null;const g=GOALS[S.lg];let ok=false;try{ok=(S.lgp|0)>=3&&g[2]()}catch(e){}return ok?{id:S.lg,n:g[0]}:{id:'fail',n:'🥀 ปณิธานที่ไม่สำเร็จ'}}
{const _cd=checkDeath;checkDeath=function(){const was=S&&S.alive;const r=_cd.apply(this,arguments);try{if(was&&S&&!S.alive&&S.lg){const E=ending();if(E){const L=LS.get('murim_ends',[])||[];const nw=!L.includes(E.id);if(nw){L.push(E.id);LS.set('murim_ends',L)}
  const tot=Object.keys(GOALS).length+1,html=`<div class="item" style="border-left:4px solid #e8c86a;margin:8px 0"><b>🏁 ฉากจบ: ${E.n}</b>${nw?' <span class="tag2">✨ ใหม่!</span>':''}<br><span class="tag2">ปณิธาน ${GOALS[S.lg][0]} · ความคืบหน้า ${S.lgp|0}/3 · สะสมฉากจบแล้ว ${L.length}/${tot} · ยังไม่เคยเห็นอีก ${tot-L.length} แบบ</span></div>`;
  let n=0;const put=()=>{const m=$('modal');if(m&&modalOpen&&m.querySelector('h3')&&!m.querySelector('.endB')){m.querySelector('h3').insertAdjacentHTML('afterend',html.replace('class="item"','class="item endB"'))}else if(n++<25)setTimeout(put,400)};setTimeout(put,600)}}}catch(e){}return r}}
