const IC={dice:'<rect x="4" y="4" width="16" height="16" rx="3"/><circle cx="9" cy="9" r="1" fill="currentColor"/><circle cx="15" cy="9" r="1" fill="currentColor"/><circle cx="9" cy="15" r="1" fill="currentColor"/><circle cx="15" cy="15" r="1" fill="currentColor"/>',
 stamp:'<circle cx="12" cy="12" r="8.5"/><path d="M8.5 12h7M12 8.5v7"/>',frame:'<rect x="4" y="4" width="16" height="16" rx="2"/><rect x="8" y="8" width="8" height="8" rx="1"/>',
 lantern:'<path d="M9 4h6M8 7h8a2 2 0 0 1 2 2v6a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2V9a2 2 0 0 1 2-2zM10 17v3M14 17v3M12 7v10"/>',tag:'<path d="M4 5h9l7 7-8 8-8-8z"/><circle cx="8.5" cy="9.5" r="1" fill="currentColor"/>',
 bolt:'<path d="M13 3 5 13h6l-1 8 8-10h-6z"/>',yin:'<circle cx="12" cy="12" r="8.5"/><path d="M12 3.5a4.25 4.25 0 0 1 0 8.5 4.25 4.25 0 0 0 0 8.5"/>',inf:'<path d="M12 12c-2-3-3.5-4-5.2-4a4 4 0 0 0 0 8c1.7 0 3.200-1 5.200-4zm0 0c2 3 3.500 4 5.200 4a4 4 0 0 0 0-8c-1.700 0-3.200 1-5.200 4z"/>',
 plaque:'<path d="M7 20V9a5 5 0 0 1 10 0v11zM9.500 12h5M9.500 15h5"/>',ticket:'<path d="M4 8a2 2 0 0 0 0 4v0a2 2 0 0 1 0 4v1h16v-1a2 2 0 0 1 0-4v0a2 2 0 0 0 0-4V7H4zM10 7v10"/>',chev:'<path d="m9 6 6 6-6 6"/>',check:'<path d="m5 12 4.500 4.500L19 7"/>'};
const ico=n=>`<svg class="vxi" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${IC[n]||''}</svg>`;
const seal=(t,x)=>{const v=vget();return`<span class="vseal vs${t}${x||''}"><b>${t===3&&v&&v.ul?'№'+v.ul.o:SLb[t]}</b></span>`};
let TT={tt:'',ttl:[]};try{const o=LS.get('murim_vipt',null);if(o)TT=o}catch(e){}
const pend=()=>{let P=null;try{P=LS.get('murim_vipP',null)}catch(e){}if(P&&Date.now()-P.t>7*864e5){try{LS.set('murim_vipP',null)}catch(e){}P=null}return P};
const setPend=P=>{try{LS.set('murim_vipP',P)}catch(e){}};
const kdGet=()=>{const t=new Date(Date.now()+7*3600e3).toISOString().slice(0,10);let d=null;try{d=LS.get('murim_rrk',null)}catch(e){}if(!d||d.d!==t)d={d:t,n:0};return d};
const inRR=()=>{const m=$('modal');return m&&m.querySelector('.vx-rr')};
const inVip=()=>{const m=$('modal');return m&&m.querySelector('.vx-vip')};

// ---------- สถานะการจ่าย (ไทม์ไลน์ 3 ขั้น) ----------
function tlHtml(P){if(!P)return'';const h=(Date.now()-P.t)/36e5,ago=h<1?'เมื่อสักครู่':h<24?`${Math.floor(h)} ชม.ที่แล้ว`:`${Math.floor(h/24)} วันที่แล้ว`;
 const what=P.k?NM[PK[P.k][1]]+(P.k==='v3'?'':' · 30 วัน'):`แพ็กสุ่มเกิด ${P.n||''} ครั้ง`;
 return`<div class="vx-tl"><div class="vx-tlh"><b>รายการที่รอตรวจ</b><small>${what}</small></div>
 <ol><li class="done"><i>${ico('check')}</i><div><b>ส่งสลิปแล้ว</b><small>${ago}</small></div></li>
 <li class="now"><i></i><div><b>ผู้พัฒนากำลังตรวจสลิป</b><small>ปกติไม่เกิน 1 วัน${h>48?' · <span style="color:#e0503c">เกิน 48 ชม.แล้ว แจ้งบั๊กเพื่อขอคืนเงินได้</span>':''}</small></div></li>
 <li><i></i><div><b>ได้รับสิทธิ์</b><small>สิทธิ์เข้าเองและมีแจ้งเตือน ไม่ต้องทำอะไรเพิ่ม</small></div></li></ol>
 <button class="gbtn" onclick="vxCheck(this)">เช็กสถานะตอนนี้</button></div>`}
window.vxCheck=async function(b){if(b)b.disabled=true;try{await vxFetch(true)}catch(e){toast('เช็กไม่สำเร็จ ลองใหม่อีกครั้ง')}if(b)b.disabled=false;const P=pend();if(P&&b)toast('ยังไม่ได้รับการอนุมัติ รอผู้พัฒนาตรวจสลิปนะ')};
async function vxFetch(re){const RR=window._RR||{};const j=await api('rrget');if(!j)return;RR.c=Math.max(0,+j.c||0);if(j.pk)RR.pk=j.pk;
 if(j.vip){TT={tt:j.vip.tt||'',ttl:j.vip.ttl||TT.ttl||[]};try{LS.set('murim_vipt',TT)}catch(e){}}
 try{window.vipSet&&window.vipSet(j.vip)}catch(e){}
 if(re){if(inRR())rrMenu();else if(inVip())vipMenu()}}

// ---------- หน้า 🎲 สุ่มเกิดเพิ่ม ----------
window.rrMenu=function(){const RR=window._RR||{pk:{},used:0,cap:10,kday:5,kc:1000},kb=kbGet(),kk=Math.max(kb.g,kb.e),cap=RR.used>=RR.cap,kd=kdGet(),kc=window.rrKC?window.rrKC():1000,kOut=kd.n>=RR.kday,t=T(),v=vget(),P=pend();
 const pk=Object.entries(RR.pk||{}),u0=pk.length?pk[0][1][0]/pk[0][1][1]:1;
 const ent=t?`<button class="vx-ent" onclick="vipMenu()">${seal(t,' mini')}<span><b>${NM[t]}</b><small>${t===3?(v.ul?'ลำดับที่ '+v.ul.o:'ตลอดไป'):'อีก '+daysLeft(v,t)+' วัน'} · สุ่มเกิด ${[0,30,60,100][t]} ครั้งต่อชีวิต</small></span><span class="go">${ico('chev')}</span></button>`
  :`<button class="vx-ent" onclick="vipMenu()"><span class="vx-ei">${ico('lantern')}</span><span><b>ผู้สนับสนุน</b><small>สุ่มเกิด 30–100 ครั้งต่อชีวิต · ตราประทับ · กรอบ · ฉายา</small></span><span class="go">${ico('chev')}</span></button>`;
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3 class="vx-rr">สุ่มเกิดเพิ่ม</h3>
 ${ent}${t>=2?'<button class="vx-auto" onclick="vipAutoMenu()">'+ico('bolt')+'<span>สุ่มรัว <small>ตั้งเงื่อนไขแล้วระบบสุ่มให้เอง</small></span></button>':''}
 <div class="vx-chips"><div><b>${rerolls}</b><span>ฟรี</span></div><div><b>${RR.c==null?'…':fmt(RR.c)}</b><span>ซื้อไว้</span></div><div><b>${RR.used||0}/${RR.cap||10}</b><span>ใช้เพิ่มชีวิตนี้</span></div></div>
 ${cap?`<p class="tag2" style="color:#e0503c;margin:0 0 8px">ชีวิตนี้ใช้ครบ ${RR.cap} ครั้งแล้ว สิทธิ์ที่ซื้อเก็บไว้ใช้ชีวิตหน้าได้</p>`:''}
 <div class="vx-act">${ico('ticket')}<div class="tx"><b>ใช้สิทธิ์ที่ซื้อไว้</b><small>เหลือ ${RR.c==null?'…':fmt(RR.c)} ครั้ง</small></div><button class="gbtn" ${cap||!RR.c?'disabled':''} onclick="rrUsePaid(this)">ใช้ 1 ครั้ง</button></div>
 <div class="vx-act">${ico('yin')}<div class="tx"><b>ใช้กรรมแลก</b><small>${kOut?'วันนี้แลกครบแล้ว':`ครั้งนี้ ${fmt(kc)} กรรม`} · มี ${fmt(kk)}<br>แลกแล้ว ${kd.n}/${RR.kday} ครั้งวันนี้ · ราคาเท่าตัวทุกครั้ง รีเซ็ตเที่ยงคืน</small></div><button class="gbtn" ${cap||kOut||kk<kc?'disabled':''} onclick="rrUseKarma()">แลก 1 ครั้ง</button></div>
 ${P?tlHtml(P):''}
 <h4 class="vx-h4">ซื้อสิทธิ์สุ่มเกิด</h4>
 <div class="vx-packs">${pk.map(([k,x],i)=>{const per=x[0]/x[1],sv=Math.round((1-per/u0)*100),best=i===pk.length-1&&pk.length>1;return`<button class="vx-pk${best?' best':''}" onclick="rrBuy('${k}')">${best?'<span class="vx-rib">คุ้มสุด</span>':''}<span class="n">${x[1]}</span><span class="u">ครั้ง</span><span class="s">${sv>0?'ถูกกว่า '+sv+'%':'&nbsp;'}</span><span class="p">${x[0]} บาท</span><span class="u">${per.toFixed(2)} บ./ครั้ง</span></button>`}).join('')}</div>
 <p class="vx-note">ไม่ซื้อก็เล่นได้เหมือนกัน สุ่มฟรี 5 ครั้ง และแลกกรรมเพิ่มได้ทุกวัน · สิทธิ์ที่ซื้อไม่มีวันหมดอายุ</p>
 <details class="vfp"><summary>เงื่อนไขการซื้อ</summary><p class="tag2">สิทธิ์ผูกกับบัญชีคุณ (ล็อกอิน Google ไว้จะไม่หายเวลาเปลี่ยนเครื่อง) · แนบสลิปแล้วระบบตรวจอัตโนมัติ สิทธิ์เข้าทันที (ถ้าตรวจอัตโนมัติไม่ได้ ผู้พัฒนาตรวจให้ ปกติไม่เกิน 1 วัน) · ถ้าเกิน 48 ชม. ยังไม่ได้ แจ้งบั๊กเพื่อขอคืนเงินได้ · ไม่มีการตัดเงินอัตโนมัติ</p></details>`);
 if(RR.c==null&&!RR.ld){RR.ld=1;vxFetch(false).catch(()=>{}).then(()=>{RR.ld=0;if(inRR())rrMenu()})}}

// ---------- หน้า VIP ----------
const F=(ic,x)=>`<li>${ico(ic)}<span>${x}</span></li>`;
function card(k){const n=PK[k][1],t=T(),v=vget(),have=t===n,low=t===3&&n<3;
 const L={1:[F('dice','สุ่มเกิดได้ <b>30 ครั้ง</b>ต่อชีวิต'),F('dice','🔒 ตั๋วล็อกชะตา <b>2 ใบ</b> ทุกรอบ 30 วัน'),F('dice','🔒 ล็อกคำตอบ <b>5 ช่อง</b> ให้ชะตาเลือกคำตอบเดิมให้'),F('stamp','ตราประทับชาด <b>เส้นเดี่ยว</b>'),F('frame','กรอบอวตารเส้นเดี่ยวสีชาด'),F('lantern','ป้ายโคมหน้าชื่อในแชท'),F('tag','ฉายา เลือกจากชุดสำเร็จรูป 6 ชื่อ')],
  2:[F('dice','สุ่มเกิดได้ <b>60 ครั้ง</b>ต่อชีวิต'),F('dice','🔒 ตั๋วล็อกชะตา <b>6 ใบ</b> ทุกรอบ 30 วัน'),F('dice','🔒 ล็อกคำตอบ <b>10 ช่อง</b> ให้ชะตาเลือกคำตอบเดิมให้'),F('stamp','ตราประทับชาด <b>เส้นคู่</b>'),F('frame','กรอบอวตารเส้นคู่'),F('yin','แลกกรรมสุ่มได้วันละ <b>8 ครั้ง</b> (ปกติ 5)'),F('bolt','ปุ่ม <b>สุ่มรัว</b> ตั้งเงื่อนไขแล้วระบบสุ่มให้เอง'),F('tag','ฉายาเลือกจากชุดสำเร็จรูป')],
  3:[F('dice','สุ่มเกิดได้ <b>100 ครั้ง</b>ต่อชีวิต ตลอดไป'),F('dice','🔒 ตั๋วล็อกชะตา <b>10 ใบ</b>ทันที + <b>เดือนละ 5</b> ตลอดไป'),F('dice','🔒 ล็อกคำตอบ <b>20 ช่อง</b> ให้ชะตาเลือกคำตอบเดิมให้'),F('stamp','ตราทองแกะลาย พร้อม <b>เลขลำดับ</b> ซื้อซ้ำไม่ได้'),F('frame','กรอบขอบทองเส้นคู่ ประดับมุม'),F('plaque','ป้ายชื่อในหอผู้ก่อตั้ง · คำจารึก · จุดธูป'),F('tag','ฉายา <b>ตั้งเองได้</b> (20 ตัวอักษร)'),F('bolt','ทุกอย่างของผู้อาวุโส ตลอดไป')]}[n];
 const price=n===3?'ครั้งเดียว ตลอดไป':'/ 30 วัน',lbl=have&&n<3?`ต่ออายุ ${PK[k][0]} บาท · 30 วัน`:n===3?`ซื้อตลอดไป ${PK[k][0]} บาท`:`สมัคร ${PK[k][0]} บาท · 30 วัน`;
 const cmp=n===3?`<div class="vx-cmp"><div><span>30 วัน 99 × 6</span><i style="width:99%"></i><b>594</b></div><div><span>ตลอดไป</span><i style="width:100%" class="g"></i><b>599</b></div><p>จ่ายครั้งเดียว คุ้มตั้งแต่เดือนที่ 7 · ไม่ต้องต่ออายุอีก</p></div>`:'';
 const dis=(n===3&&t===3)||low;
 return`<div class="vx-card vk${n}${have?' on':''}${low?' dim':''}">${n===3?'<span class="vx-rib g">คุ้มสุด · ตลอดไป</span>':''}${have?'<span class="vx-rib o">ใช้อยู่</span>':''}
 <div class="vx-hd">${seal(n,'')}<div><div class="vx-nm">${NM[n]}</div><div class="vx-pr">${PK[k][0]} <small>บาท ${price}</small></div></div></div>
 <ul>${L.join('')}</ul>${cmp}<button class="vx-buy vk${n}" ${dis?'disabled':''} onclick="vipBuy('${k}')">${n===3&&t===3?'เป็นผู้ก่อตั้งแล้ว':low?'มีสิทธิ์ถาวรอยู่แล้ว':lbl}</button></div>`}
function ttHtml(){const t=T();if(!t)return'';const cur=TT.tt||'';
 const body=t===3?`<div class="vx-ttin"><input id="vipT" maxlength="20" placeholder="ตั้งฉายาคุณ (ไม่เกิน 20 ตัวอักษร)" value="${esc(cur)}"><button class="gbtn" onclick="vipTtl(document.getElementById('vipT').value)">บันทึก</button></div>`
  :`<div class="vx-tt">${(TT.ttl||[]).map(n=>`<button class="${n===cur?'on':''}" data-w="${esc(n)}" onclick="vipTtl(this.dataset.w)">${esc(n)}</button>`).join('')||'<small class="tag2">กำลังโหลด…</small>'}</div>`;
 return`<div class="vx-sec"><h4 class="vx-h4">ฉายาคุณ</h4><p class="tag2" style="margin:0 0 6px">${cur?'ตอนนี้: <b>'+esc(cur)+'</b> · ':''}แสดงข้างชื่อในแชท${t<3?' · กดซ้ำที่ชื่อเดิมเพื่อถอด':''}</p>${body}</div>`}
window.vipTtl=async function(w){w=String(w||'').trim();if(w&&w===TT.tt&&T()<3)w='';try{const j=await api('vipttl',{w});TT.tt=j.tt||'';try{LS.set('murim_vipt',TT)}catch(e){}toast(TT.tt?'ตั้งฉายาแล้ว':'ถอดฉายาแล้ว');if(inVip())vipMenu()}catch(e){toast(e.message==='preset'?'เลือกจากชุดที่มีให้':'บันทึกไม่สำเร็จ ลองใหม่อีกครั้ง')}};
window.vipMenu=function(){const t=T(),v=vget(),near=t&&t<3&&(endOf(v,t)-Date.now())<3*864e5,P=pend();
 const stat=t?`<div class="vx-stat">${seal(t,near?' fade':'')}<div><b>${NM[t]}</b><small>${t===3?(v.ul?`ลำดับที่ ${v.ul.o} · เข้าร่วม ${dTxt(v.ul.t)}`:'ตลอดไป'):`ถึง ${dTxt(endOf(v,t))} · อีก ${daysLeft(v,t)} วัน${near?' · ใกล้หมดอายุ':''}`}</small></div></div>`:'';
 const ins=t===3&&v.ul?`<div class="vx-sec"><h4 class="vx-h4">คำจารึกบนป้าย</h4><div class="vx-ttin"><input id="vipW" maxlength="40" placeholder="ข้อความสั้นๆ (ไม่เกิน 40 ตัวอักษร)" value="${esc(v.ul.w||'')}"><button class="gbtn" onclick="vipSay(this)">จารึก</button></div></div>`:'';
 modal(`<button class="xbtn" onclick="rrMenu()">✕</button><h3 class="vx-vip">ผู้สนับสนุน</h3>
 <div class="vx-free"><b>เล่นฟรีก็เล่นได้เหมือนกัน ไม่ต้องน้อยใจ</b><details><summary>อ่านรายละเอียด</summary><p>ผู้สนับสนุนไม่ได้พลัง เงิน หรือโบนัสในเกม ได้แค่สุ่มเกิดมากขึ้น กับตราประทับ กรอบ และฉายา ชีวิตทุกคนต้องเล่นเองทั้งชีวิตและแข่งทำเนียบด้วยกติกาเดียวกัน · สายฟรีสุ่มเกิดได้ 5 ครั้งต่อชีวิต และแลกกรรมเพิ่มได้ทุกวัน</p></details></div>
 ${stat}${P?tlHtml(P):''}${ins}${ttHtml()}
 ${card('v1')}${card('v2')}${card('v3')}
 <button class="vx-wallb" onclick="vipWall()">${ico('plaque')}<span>เข้าหอผู้ก่อตั้ง<small>ป้ายผู้ก่อตั้ง · อันดับผู้สนับสนุน (อยู่ในหน้าเดียวกัน)</small></span><span class="go">${ico('chev')}</span></button>
 <details class="vfp"><summary>เงื่อนไขการซื้อ</summary><p class="tag2">ไม่ต่ออายุเอง ไม่มีการตัดเงินอัตโนมัติ · ซื้อซ้ำก่อนหมดอายุจะต่อวันให้ · สิทธิ์ผูกกับบัญชี (ล็อกอิน Google ไว้จะไม่หายเวลาเปลี่ยนเครื่อง) · แนบสลิปแล้วระบบตรวจอัตโนมัติ สิทธิ์เข้าทันที (ถ้าตรวจอัตโนมัติไม่ได้ ผู้พัฒนาตรวจให้ ปกติไม่เกิน 1 วัน) · ถ้าเกิน 48 ชม. ยังไม่ได้ แจ้งบั๊กเพื่อขอคืนเงินได้ · สิทธิ์สุ่มที่ซื้อเป็นแพ็กไม่หายเมื่อ VIP หมดอายุ</p></details>`);
 if(!vipMenu._ld){vipMenu._ld=1;const a=JSON.stringify([vget(),TT]);vxFetch(false).catch(()=>{}).then(()=>{vipMenu._ld=0;if(inVip()&&a!==JSON.stringify([vget(),TT]))vipMenu()})}};

// ---------- หน้าชำระเงิน: ขั้นตอน 3 ข้อ + จำสถานะ ----------
const steps=()=>`<ol class="vx-st"><li><i>1</i>สแกนโอน</li><li><i>2</i>แนบสลิป</li><li><i>3</i>สิทธิ์เข้า</li></ol>`;
for(const f of ['vipBuy','rrBuy']){const o=window[f];if(typeof o!=='function')continue;window[f]=function(){const r=o.apply(this,arguments);try{const h=$('modal').querySelector('h3');if(h&&!$('modal').querySelector('.vx-st'))h.insertAdjacentHTML('afterend',steps())}catch(e){}return r}}
