{const _f=fight;fight=function(n,ep){try{const x=on()&&S.sys.x;if(x&&x.bf&&x.bf.n>0&&!fight._sx){ep=ep*x.bf.m;x.bf.n--;if(x.bf.n<=0)x.bf=null}}catch(e){}return _f.call(this,n,ep)}}
{const _d=duel;duel=function(n,ep,cb){try{const x=on()&&S.sys.x;if(x&&x.bf&&x.bf.n>0){ep=ep*x.bf.m;x.bf.n--;if(x.bf.n<=0)x.bf=null}}catch(e){}fight._sx=1;try{return _d.call(this,n,ep,cb)}finally{fight._sx=0}}}
// กันตาย: สกิลกันตาย · ฉากจบ "ปล่อยระบบเป็นอิสระ" ช่วยทุก 40 ปี · พันธมิตรช่วยครั้งเดียว
{const _rt=regTry;regTry=function(cause){try{if(on()&&!/วัยชรา/.test(cause||'')){const x=X();
  if(x.gd){x.gd=0;S.hp=Math.round(S.maxHp*.35);S.deathCause=null;sl(`🛡️ <b>${esc(DT().sk.find(k=>k[3]==='ward')?DT().sk.find(k=>k[3]==='ward')[1]:'พลังกันตาย')}</b> ทำงาน — "${esc(line())}"`,'myth');sxPop('🛡️ ตรวจพบความตายของโฮสต์','ใช้พลังกันตาย… ชีพจรกลับมาแล้ว','gold');return true}
  if(x.end==='free'&&S.age-(x.svY==null?-999:x.svY)>=40){x.svY=S.age;S.hp=Math.round(S.maxHp*.3);S.deathCause=null;sl('🕊️ ระบบที่เป็นอิสระแล้วดึงคุณกลับมาเอง "ข้ายังไม่อยากอยู่คนเดียว"','myth');return true}
  if(x.al&&!x.al.dead&&!x.al.saved&&x.al.st==='ok'&&Math.random()<.6){x.al.saved=1;S.hp=Math.round(S.maxHp*.25);S.deathCause=null;sl(`🤝 ${esc(x.al.n)} โฮสต์พันธมิตรฉีกหน้าต่างระบบตัวเองเพื่อดึงคุณกลับมา`,'myth');return true}}}catch(e){console.error(e)}return _rt.apply(this,arguments)}}

// ---------- EXP: เกิน Lv.100 ช้าลงตามเลเวล · จับหลักไมล์ทุก 10 เลเวล ----------
{const _bs=bindSys;bindSys=function(){const r=_bs.apply(this,arguments);try{if(S&&S.sys)X()}catch(e){}return r}}
{const _ge=gainExp;gainExp=function(n){try{if(S&&S.sys){X();if(S.sys.lv>=100)n=n*100/S.sys.lv}}catch(e){}const b=S&&S.sys?S.sys.lv:0;const r=_ge.call(this,n);try{if(S&&S.sys&&S.sys.lv>b){const x=X(),m=Math.floor(S.sys.lv/10);if(m>(x.ms||0)){x.mq=(x.mq||0)+(m-(x.ms||0));x.ms=m}
  DT().sk.forEach(k=>{if(b<k[0]&&S.sys.lv>=k[0]){sl(`🔓 <b>แพตช์ปลดล็อก:</b> สกิล「${esc(k[1])}」 — ${esc(k[2])} · กดใช้ได้ในหน้าต่างระบบ`,'myth');sxPop(`🔓 ปลดล็อกสกิล: ${esc(k[1])}`,esc(k[2]),'gold')}})}}catch(e){}return r}}
const PERK={sharp:['🗡️ คมขึ้น','สกิลลดพลังศัตรูได้มากขึ้น'],cdr:['⏱️ เร็วขึ้น','คูลดาวน์สกิลทุกตัว −1 ปี'],cool:['❄️ ระบายความร้อน','ภาระจากสกิลลดลง 40%'],yr:['📈 ดอกเบี้ยระบบ','พลังเพิ่มทุกปีตามเลเวลระบบ'],mend:['💚 ซ่อมตัวเอง','ฟื้นพลังชีวิตทุกปี'],luck:['🍀 บั๊กดี','ระบบรวนแล้วมักออกผลดี'],sp:['💠 SP ไหลเวียน','ได้ SP ทุกปี'],life:['⏳ อายุระบบ','อายุขัยเพิ่มเล็กน้อยทุกปี']};
function milestone(){const x=X(),s=S.sys,lv=s.lv,pv=`v${x.v}.${Math.floor(lv/10)}`,av=Object.keys(PERK).filter(k=>!x.pk.includes(k));
 const bug=Math.random()<.12;
 const o=[O(`📊 อัปเกรดค่าสถานะ`,`+${8*x.v} แต้มสถานะ`,()=>{s.pts+=8*x.v;if(auto)autoAlloc();sl(`📦 แพตช์ ${pv}: แต้มสถานะ +${8*x.v}`,'up')}),
  O(`💠 คลัง SP`,`+${120*x.v} SP`,()=>{s.sp+=120*x.v;sl(`📦 แพตช์ ${pv}: SP +${120*x.v}`,'up')})];
 if(av.length){const p=pk(av);o.push(O(`${PERK[p][0]}`,`ความสามารถถาวร: ${PERK[p][1]}`,()=>{x.pk.push(p);sl(`📦 แพตช์ ${pv}: ได้ความสามารถถาวร <b>${PERK[p][0]}</b> — ${PERK[p][1]}`,'myth')}))}
 else o.push(O('🌌 แพตช์ทดลอง','ไม่รู้ว่าจะได้อะไร',()=>{const r=Math.random();if(r<.5){S.power+=pctPow(.08*x.v);sl('🌌 แพตช์ทดลองสำเร็จ พลังพุ่ง','myth')}else if(r<.8){s.sp+=200*x.v;sl('🌌 แพตช์ทดลองคายเศษ SP ออกมาเต็มหน้าต่าง','up')}else{x.ld=Math.min(150,x.ld+50);sl('🌌 แพตช์ทดลองพัง ระบบร้อนจัด','fail')}}));
 sxPop(`📦 แพตช์อัปเดต ${pv}`,bug?'⚠️ ตรวจพบไฟล์แปลกปลอม':'กำลังติดตั้ง…',bug?'bug':'');choice(`🟦 แพตช์อัปเดต ${pv}`,`<span class="px">[ระบบ]</span> ถึงหลักไมล์ Lv.${lv}${lv>=100?` (★${Math.floor((lv-100)/10)+1})`:''} — เลือกสิ่งที่จะติดตั้ง${bug?'<br><span class="tag2">⚠️ ตรวจพบไฟล์แปลกปลอมในแพตช์นี้…</span>':''}`,o);
 if(bug)setTimeout(()=>{try{if(on())glitch(1)}catch(e){}},50)}

// ---------- ร่างตามโลก (อัปเกรดใหญ่) ----------
function upgrade(v){const x=X(),s=S.sys,F=DT().F[v]||'ระบบ',o=x.v;x.v=v;
 sxPop(`${VI[v]} SYSTEM UPGRADE`,`ตรวจพบโลก${VN[v]} — กำลังติดตั้ง ${esc(F)} v${v}.0`,'gold');
 choice(`${VI[v]} ระบบอัปเกรด: ${F}`,`<span class="px">[ระบบ]</span> ตรวจพบโฮสต์เข้าสู่<b>โลก${VN[v]}</b>… โครงสร้างเดิมรับพลังของโลกนี้ไม่ไหว<br>กำลังติดตั้ง <b>${esc(F)}</b> (v${v}.0)<br><br><i>"${esc(line())}"</i>`,[
  O('🧠 เก็บความทรงจำทั้งหมด','ความเชื่อใจ + · ได้เบาะแสความจริงของระบบ',()=>{x.tr=cl(x.tr+15,0,100);x.cl++;x.cd={};sl(`💾 ย้ายความทรงจำสำเร็จ ระบบจำทุกอย่างที่ผ่านมากับคุณ · <b>${esc(F)}</b>`,'myth')}),
  O('🔄 ฟอร์แมตใหม่หมด','SP และแต้มสถานะก้อนใหญ่ · ความเชื่อใจลดลง',()=>{s.sp+=400*v;s.pts+=15*v;x.tr=cl(x.tr-12,0,100);if(auto)autoAlloc();sl(`🔄 ฟอร์แมตเสร็จ ระบบเงียบไปครู่หนึ่ง แล้วทักคุณเหมือนคนแปลกหน้า · <b>${esc(F)}</b>`,'up')}),
  O('🧬 ปล่อยให้กลายพันธุ์','สุ่ม อาจได้ความสามารถถาวรสองอย่าง หรือเสียหาย',()=>{const r=Math.random(),av=Object.keys(PERK).filter(k=>!x.pk.includes(k));if(r<.6&&av.length){const a=av.sort(()=>Math.random()-.5).slice(0,2);x.pk.push(...a);sl(`🧬 ระบบกลายพันธุ์เป็นร่างที่ไม่มีในคู่มือ ได้ ${a.map(k=>PERK[k][0]).join(' และ ')}`,'myth')}else{x.ld=120;S.hp=Math.max(1,Math.round(S.hp*.5));sl('🧬 การกลายพันธุ์ล้มเหลวครึ่งทาง ระบบร้อนจัดและดึงพลังชีวิตคุณไปครึ่งหนึ่ง','fail')}})]);
 if(o<v)try{S.key.push(`${S.age} ปี — ระบบอัปเกรดเป็น ${F}`)}catch(e){}}

