 if(x.al&&x.al.st==='ok')S.power+=(2+s.lv)*S.talent.m;
 if(x.ld>=100&&Math.random()<.4){x.ld-=30;HPx(10);sl('🔥 ระบบร้อนเกิน ปวดหัวจนลุกไม่ขึ้นหลายวัน','fail');sxPop('🔥 SYSTEM OVERHEAT','โฮสต์ได้รับความเสียหาย','bug');x.tr=cl(x.tr-3,0,100)}
 // ร่างตามโลก / รีบูตข้ามกัลป์
 const v=verNow();if(v>x.v&&!choice._cur){upgrade(v);return r}
 const kn=(S.kalpa&&S.kalpa.n)|0;if(kn>(x.kn|0)){x.kn=kn;if(x.v>=4&&!choice._cur){reboot(kn);return r}}
