 if(hit){closeM();toast(n?`⚡ เจอแล้ว! ${sum}`:'⚡ ชีวิตนี้ตรงเงื่อนไขอยู่แล้ว');try{sfx('good')}catch(e){}return}
 const showBest=best&&best!==roll;
