 for(const [bx0,bc] of [[22,'#b8283a'],[138,'#2a5ab8']]){F(c,bx0,30,1,42,'#4a3a2a');F(c,bx0+1,31,6,14,bc);F(c,bx0+1,44,6,1,shadeC(bc,-.3));F(c,bx0+3,35,2,2,'#f0d070')}
